/**
 * stm32_main.c — STM32H7 firmware entry point
 *
 * Initialisation order (Phase 0 stubs):
 *   1. SystemClock_Config  → 480 MHz
 *   2. HAL peripherals     → LTDC, DMA2D, SAI/I2S, USB HS, GPIO matrix
 *   3. lv_init + hal_display_init
 *   4. app_main_init       → creates FreeRTOS tasks
 *   5. vTaskStartScheduler
 */

